local _b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local _lut = {}
for i = 1, 64 do
    _lut[string.byte(_b, i)] = i - 1
end

local function _b64dec(input)
    local len = #input
    local out = {}
    local out_len = 0
    local i = 1
    while i <= len do
        local b1 = string.byte(input, i)
        local b2 = string.byte(input, i + 1)
        local b3 = string.byte(input, i + 2)
        local b4 = string.byte(input, i + 3)
        if not b1 or not b2 then break end
        local c1 = _lut[b1]
        local c2 = _lut[b2]
        local c3 = b3 and _lut[b3] or nil
        local c4 = b4 and _lut[b4] or nil
        if not c1 or not c2 then break end
        out_len = out_len + 1
        out[out_len] = string.char((c1 * 4 + math.floor(c2 / 16)) % 256)
        if c3 then
            out_len = out_len + 1
            out[out_len] = string.char(((c2 % 16) * 16 + math.floor(c3 / 4)) % 256)
            if c4 then
                out_len = out_len + 1
                out[out_len] = string.char(((c3 % 4) * 64 + c4) % 256)
            end
        end
        i = i + 4
    end
    return table.concat(out)
end

local _bxor = (bit32 and bit32.bxor) or (bit and bit.bxor) or function(a, b)
    local r, p = 0, 1
    while a > 0 or b > 0 do
        local ra, rb = a % 2, b % 2
        if ra ~= rb then r = r + p end
        a, b, p = math.floor(a / 2), math.floor(b / 2), p * 2
    end
    return r
end

local _cipher = _b64dec(table.concat(_data_chunks))
local _klen = #_k
local _plain_parts = {}
local _c_len = #_cipher

for i = 1, _c_len do
    local cbyte = string.byte(_cipher, i)
    local kbyte = string.byte(_k, ((i - 1) % _klen) + 1)
    local salt = ((i - 1) * 7 + 13) % 256
    local pbyte = _bxor(_bxor(cbyte, salt), kbyte)
    _plain_parts[i] = string.char(pbyte)
end

local _code = table.concat(_plain_parts)
local _loader = (loadstring or load)
local _fn, _err = _loader(_code, "@ym1co_farmer_5_0")
if _fn then
    return _fn()
else
    if warn then
        warn("[ym1co farmer 5.0] Execution failure: " .. tostring(_err))
    else
        print("[ym1co farmer 5.0] Execution failure: " .. tostring(_err))
    end
end
